  if (hint) hint.textContent = "Il comunicato viene pubblicato direttamente nelle News e inviato via email a barra.silvio@gmail.com.";
  const cleanForm = form.cloneNode(true);
  cleanForm.dataset.v79DirectPublish = "1";
