  if (/RITORNO|RETURN|\bRIT\b|(^|\s)R(\s|$)/.test(legRaw)) return "ritorno";
  if (/ANDATA|FIRST|\bAND\b|(^|\s)A(\s|$)/.test(legRaw)) return "andata";
  if (/SECCA|UNICA|SINGLE|ONE\s+LEG/.test(legRaw)) return "secca";
